export interface RateLimiterOptions {
  max: number
  windowMs: number
  mode: 'fixed' | 'sliding'
  now?: () => number
}

interface FixedBucket {
  windowStart: number
  count: number
}

export class RateLimiter {
  private readonly max: number
  private readonly windowMs: number
  private readonly mode: 'fixed' | 'sliding'
  private readonly now: () => number
  private readonly fixedBuckets = new Map<string, FixedBucket>()
  private readonly slidingTimestamps = new Map<string, number[]>()

  constructor(options: RateLimiterOptions) {
    this.max = options.max
    this.windowMs = options.windowMs
    this.mode = options.mode
    this.now = options.now ?? Date.now
  }

  allow(key: string): boolean {
    const t = this.now()
    if (this.mode === 'sliding') return this.allowSliding(key, t)
    return this.allowFixed(key, t)
  }

  private allowFixed(key: string, t: number): boolean {
    const windowStart = Math.floor(t / this.windowMs) * this.windowMs
    const bucket = this.fixedBuckets.get(key)
    if (!bucket || bucket.windowStart !== windowStart) {
      this.fixedBuckets.set(key, { windowStart, count: 1 })
      return true
    }
    if (bucket.count >= this.max) return false
    bucket.count += 1
    return true
  }

  private allowSliding(key: string, t: number): boolean {
    const cutoff = t - this.windowMs
    const stamps = this.slidingTimestamps.get(key) ?? []
    let firstFresh = 0
    while (firstFresh < stamps.length && stamps[firstFresh] <= cutoff) {
      firstFresh += 1
    }
    const fresh = firstFresh === 0 ? stamps : stamps.slice(firstFresh)
    if (fresh.length >= this.max) {
      this.slidingTimestamps.set(key, fresh)
      return false
    }
    fresh.push(t)
    this.slidingTimestamps.set(key, fresh)
    return true
  }
}

import { describe, it, expect } from 'vitest'
import { RateLimiter } from '../src/rate-limiter'

describe('RateLimiter', () => {
  it('allows the first request', () => {
    const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'fixed' })
    expect(limiter.allow('user-1')).toBe(true)
  })

  it('blocks the request after max is reached in fixed mode', () => {
    const limiter = new RateLimiter({ max: 3, windowMs: 1000, mode: 'fixed' })
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('tracks independent keys separately', () => {
    const limiter = new RateLimiter({ max: 1, windowMs: 1000, mode: 'fixed' })
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-2')).toBe(true)
    expect(limiter.allow('user-1')).toBe(false)
    expect(limiter.allow('user-2')).toBe(false)
  })

  it('resets capacity at the start of the next fixed window', () => {
    let now = 0
    const limiter = new RateLimiter({
      max: 2,
      windowMs: 1000,
      mode: 'fixed',
      now: () => now,
    })
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-1')).toBe(false)
    now = 1000
    expect(limiter.allow('user-1')).toBe(true)
  })

  it('blocks sliding mode requests once trailing window is full', () => {
    let now = 0
    const limiter = new RateLimiter({
      max: 5,
      windowMs: 1000,
      mode: 'sliding',
      now: () => now,
    })
    for (let i = 0; i < 5; i++) expect(limiter.allow('user-1')).toBe(true)
    now = 500
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('sliding mode blocks across the fixed-window boundary', () => {
    let now = 999
    const limiter = new RateLimiter({
      max: 5,
      windowMs: 1000,
      mode: 'sliding',
      now: () => now,
    })
    for (let i = 0; i < 5; i++) expect(limiter.allow('user-1')).toBe(true)
    now = 1000
    expect(limiter.allow('user-1')).toBe(false)
  })

  it('sliding mode allows once oldest request ages out', () => {
    let now = 0
    const limiter = new RateLimiter({
      max: 5,
      windowMs: 1000,
      mode: 'sliding',
      now: () => now,
    })
    for (let i = 0; i < 5; i++) expect(limiter.allow('user-1')).toBe(true)
    now = 1100
    expect(limiter.allow('user-1')).toBe(true)
  })

  it('sliding mode tracks independent keys separately', () => {
    let now = 0
    const limiter = new RateLimiter({
      max: 1,
      windowMs: 1000,
      mode: 'sliding',
      now: () => now,
    })
    expect(limiter.allow('user-1')).toBe(true)
    expect(limiter.allow('user-2')).toBe(true)
    expect(limiter.allow('user-1')).toBe(false)
    expect(limiter.allow('user-2')).toBe(false)
  })
})

